CREATE TABLE IF NOT EXISTS project (id text PRIMARY KEY, user_id text NOT NULL, title text NOT NULL, genre text NOT NULL, visual_style text NOT NULL DEFAULT 'Atmospheric', style_version integer NOT NULL DEFAULT 1, logline text, status text NOT NULL DEFAULT 'Draft', created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scene (id text PRIMARY KEY, project_id text NOT NULL, user_id text NOT NULL, position integer NOT NULL, title text NOT NULL, description text NOT NULL, shot_prompt text, narration text, metadata jsonb DEFAULT '{}', created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS generation_job (id text PRIMARY KEY, project_id text NOT NULL, user_id text NOT NULL, type text NOT NULL, status text NOT NULL DEFAULT 'queued', progress integer NOT NULL DEFAULT 0, message text, payload jsonb DEFAULT '{}', error text, attempts integer NOT NULL DEFAULT 0, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS asset (id text PRIMARY KEY, project_id text NOT NULL, user_id text NOT NULL, scene_id text, type text NOT NULL, pathname text NOT NULL, mime_type text NOT NULL, size integer, metadata jsonb DEFAULT '{}', created_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS movie_export (id text PRIMARY KEY, project_id text NOT NULL, user_id text NOT NULL, status text NOT NULL DEFAULT 'queued', progress integer NOT NULL DEFAULT 0, output_asset_id text, error text, created_at timestamp NOT NULL DEFAULT now(), updated_at timestamp NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS job_event (id text PRIMARY KEY, job_id text NOT NULL, user_id text NOT NULL, status text NOT NULL, progress integer NOT NULL, message text, created_at timestamp NOT NULL DEFAULT now());
